require_once '../config/database.php';require_once '../includes/auth.php';require_role('teacher');$page_title='Панель преподавателя';
$q=$pdo->prepare('SELECT id FROM teachers WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$tid=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT COUNT(*) FROM lessons WHERE teacher_id=? AND lesson_date=CURDATE()');$q->execute([$tid]);$today=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(DISTINCT group_id) FROM lessons WHERE teacher_id=?');$q->execute([$tid]);$groups=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM grades WHERE teacher_id=?');$q->execute([$tid]);$gradeCount=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(ROUND(100*SUM(a.status IN ('PRESENT','LATE'))/NULLIF(COUNT(a.id),0),1),0) FROM attendance a JOIN lessons l ON l.id=a.lesson_id WHERE l.teacher_id=?");$q->execute([$tid]);$attendance=(float)$q->fetchColumn();
$q=$pdo->prepare("SELECT l.*,s.name subject_name,g.name group_name FROM lessons l JOIN subjects s ON s.id=l.subject_id JOIN groups g ON g.id=l.group_id WHERE l.teacher_id=? AND l.lesson_date>=CURDATE() ORDER BY l.lesson_date,l.start_time LIMIT 6");$q->execute([$tid]);$next=$q->fetchAll();include '../includes/header.php';?>
